"use strict";

// Deterministic payload builders for text-collection consistency tests and
// throughput benchmarks. No randomness: same input on every run so that
// fixtures generated by the previous (char-by-char) implementation stay
// comparable byte for byte.

const TEXT_SEED =
  "采集汇聚层统一解析各节点上报的XML报文, throughput &amp; latency &lt;must&gt; stay stable — " +
  "naïve café über señor 東京 🚀; the quick brown fox jumps over the lazy dog 0123456789. ";

/**
 * Text-dense payload: few tags, long text values, entities, unicode,
 * some CDATA sections and comments mixed in.
 * @param {number} [itemCount]
 * @returns {string}
 */
export function buildTextDenseXml(itemCount = 400) {
  const parts = ['<?xml version="1.0" encoding="UTF-8"?>\n<messages>'];
  for (let n = 0; n < itemCount; n++) {
    parts.push(`<message id="m-${n}" ts="1700000000${n % 10}">`);
    parts.push(`<title>Report ${n} — 节点${n % 17}上报</title>`);
    // long text value, ~800 chars, entity references included
    let body = "";
    for (let r = 0; r < 5; r++) {
      body += `[${n}:${r}] ` + TEXT_SEED;
    }
    parts.push(`<body>${body}</body>`);
    if (n % 7 === 0) {
      parts.push(`<payload><![CDATA[raw <xml> & "quoted" payload segment ${n} — ${TEXT_SEED}]]></payload>`);
    }
    if (n % 11 === 0) {
      parts.push(`<!-- checkpoint ${n} -->`);
    }
    parts.push(`<meta><retries>${n % 5}</retries><trace>t-${n}-αβγ</trace></meta>`);
    parts.push(`</message>`);
  }
  parts.push("</messages>");
  return parts.join("\n");
}

/**
 * Tag-dense payload: many small tags, attributes, self-closing tags,
 * short or empty text values.
 * @param {number} [itemCount]
 * @returns {string}
 */
export function buildTagDenseXml(itemCount = 3000) {
  const parts = ['<?xml version="1.0" encoding="UTF-8"?>\n<catalog>'];
  for (let n = 0; n < itemCount; n++) {
    parts.push(
      `<item id="i-${n}" cls="c${n % 13}" flag="${n % 2}" code="x${n % 97}">` +
      `<a>${n % 10}</a><b>v${n % 7}</b><c/><d e="f${n % 3}" g="h"/>` +
      `<e><f><g>${n % 100}</g><h i="j${n % 5}">x</h></f></e>` +
      `</item>`
    );
  }
  parts.push("</catalog>");
  return parts.join("");
}
